INSERT INTO notificacao (usuario_id, tipo, mensagem, titulo, link, lead_id, lead_nome, lida, data_criacao) SELECT u.id, 'CLIENTE_RECEBIDO', 'Você recebeu o cliente ' || l.nome || ' na sua carteira.', 'Novo cliente na carteira', '/leads', l.id, l.nome, (l.rn > 2), l.data_criacao FROM usuario u JOIN (SELECT id, nome, data_criacao, corretor_id, row_number() OVER (ORDER BY data_criacao DESC) AS rn FROM lead WHERE observacao = 'demo-indicadores' AND corretor_id = (SELECT id FROM usuario WHERE email = 'juliana.prado@crm.com') ORDER BY data_criacao DESC LIMIT 3) l ON l.corretor_id = u.id WHERE u.email = 'juliana.prado@crm.com';
INSERT INTO notificacao (usuario_id, tipo, mensagem, titulo, link, lead_id, lead_nome, lida, data_criacao) SELECT u.id, 'CLIENTE_RECEBIDO', 'Você recebeu o cliente ' || l.nome || ' na sua carteira.', 'Novo cliente na carteira', '/leads', l.id, l.nome, (l.rn > 2), l.data_criacao FROM usuario u JOIN (SELECT id, nome, data_criacao, corretor_id, row_number() OVER (ORDER BY data_criacao DESC) AS rn FROM lead WHERE observacao = 'demo-indicadores' AND corretor_id = (SELECT id FROM usuario WHERE email = 'thiago.alves@crm.com') ORDER BY data_criacao DESC LIMIT 3) l ON l.corretor_id = u.id WHERE u.email = 'thiago.alves@crm.com';
